import React, { useState, useEffect } from 'react';
import StockSearch from './components/StockSearch';
import StockTable from './components/StockTable';
import './App.css';

function App() {
    const [stocks, setStocks] = useState([]);

    useEffect(() => {
        // Load favorites when component mounts
        fetchFavorites();
    }, []);

    const fetchFavorites = async () => {
        try {
            const response = await fetch('http://localhost:8082/api/stocks/favorites');
            if (response.ok) {
                const favorites = await response.json();
                setStocks(favorites);
            }
        } catch (error) {
            console.error('Error fetching favorites:', error);
        }
    };

    const handleStockFound = (stock) => {
        setStocks(prevStocks => {
            const exists = prevStocks.some(s => s.symbol === stock.symbol);
            if (exists) {
                return prevStocks.map(s => s.symbol === stock.symbol ? stock : s);
            }
            return [stock, ...prevStocks];
        });
    };

    return (
        <div className="app">
            <header className="app-header">
                <h1>BörsVy</h1>
                <p>Real-time Stock Market Tracker</p>
            </header>
            <main className="app-main">
                <StockSearch onStockFound={handleStockFound} />
                {stocks.length > 0 ? (
                    <StockTable stocks={stocks} />
                ) : (
                    <div className="empty-state">
                        <p>No stocks added yet. Search for a stock symbol above to get started!</p>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
